import vectorData from './vector.json';

// vector.json is generated by export_vector_json.py from the trained model
// artifacts (internal_vector*.npy + *_meta.json). Do not edit by hand.
const targetVector: number[] = vectorData.vector;
const SCALE: number = vectorData.scale;
const BIAS: number = vectorData.bias;

export function scoreEmbedding(embedding: number[]): { cosine: number, probability: number } {
  // L2 normalize
  let norm = 0;
  for (let i = 0; i < embedding.length; i++) {
    norm += embedding[i] * embedding[i];
  }
  norm = Math.sqrt(norm);
  if (norm < 1e-12) norm = 1e-12;

  // Dot product
  let cos = 0;
  for (let i = 0; i < targetVector.length; i++) {
    cos += (embedding[i] / norm) * targetVector[i];
  }

  // Sigmoid
  const probability = 1.0 / (1.0 + Math.exp(-(SCALE * cos + BIAS)));
  return { cosine: cos, probability };
}
